SELECT products.category, CASE WHEN products.stock_qty >= 380 THEN 'high' WHEN products.stock_qty >= 113 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, ROUND(STDDEV(order_items.unit_price), 2) AS stddev_unit_price FROM order_items LEFT JOIN products ON order_items.product_id = products.id INNER JOIN orders ON order_items.order_id = orders.id GROUP BY products.category, CASE WHEN products.stock_qty >= 380 THEN 'high' WHEN products.stock_qty >= 113 THEN 'mid' ELSE 'low' END;
